{
  "PROP-6a4369e9-inv-026": {
    "property_id": "PROP-6a4369e9-inv-026",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-026",
      "classification": "vulnerability",
      "code_path": "beacon_node/network/src/network_beacon_processor/rpc_methods.rs::handle_data_columns_by_root_request_inner::L408-460",
      "proof_trace": "Data columns are added to cache during KZG verification (block_verification.rs:1324-1332) BEFORE state transition validation (per_block_processing at L1614-1629). When blocks fail state transition, their columns remain in cache. RPC handler serves cached columns without checking if the block passed state transition, violating the invariant.",
      "attack_scenario": "Attacker sends invalid block via RPC; KZG verification caches its data columns before state transition runs; block fails per_block_processing and is rejected; columns remain cached; honest peer requests DataColumnsByRoot and receives columns for the invalid block.",
      "checklist_id": "PROP-6a4369e9-inv-026"
    },
    "text": "Sidecars must not be served for blocks failing beacon-chain state transition.",
    "assertion": "forall sidecar in resp: state_transition_valid(sidecar.block) == true",
    "covers": "SG-009",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

