    29→/// Provides a single-item cache which allows for attesting to blocks before those blocks have
    30→/// reached the database.
    31→///
    32→/// This cache stores enough information to allow Lighthouse to:
    33→///
    34→/// - Produce an attestation without using `chain.canonical_head`.
    35→/// - Verify that a block root exists (i.e., will be imported in the future) during attestation
    36→///   verification.
    37→/// - Provide a block which can be sent to peers via RPC.
    38→#[derive(Default)]
    39→pub struct EarlyAttesterCache<E: EthSpec> {
    40→    item: RwLock<Option<CacheItem<E>>>,
    41→}
    42→
    43→impl<E: EthSpec> EarlyAttesterCache<E> {
    44→    /// Removes the cached item, meaning that all future calls to `Self::try_attest` will return
    45→    /// `None` until a new cache item is added.
    46→    pub fn clear(&self) {
    47→        *self.item.write() = None
    48→    }
    49→
    50→    /// Updates the cache item, so that `Self::try_attest` with return `Some` when given suitable
    51→    /// parameters.
    52→    pub fn add_head_block(
    53→        &self,
    54→        beacon_block_root: Hash256,
    55→        block: &AvailableBlock<E>,
    56→        proto_block: ProtoBlock,
    57→        state: &BeaconState<E>,
    58→        spec: &ChainSpec,
    59→    ) -> Result<(), Error> {
    60→        let epoch = state.current_epoch();
    61→        let committee_lengths = CommitteeLengths::new(state, spec)?;
    62→        let source = state.current_justified_checkpoint();
    63→        let target_slot = epoch.start_slot(E::slots_per_epoch());
    64→        let target = Checkpoint {
    65→            epoch,
    66→            root: if state.slot() <= target_slot {
    67→                beacon_block_root
    68→            } else {
    69→                *state.get_block_root(target_slot)?
    70→            },
    71→        };
    72→
    73→        let (blobs, data_columns) = match block.data() {
    74→            AvailableBlockData::NoData => (None, None),
    75→            AvailableBlockData::Blobs(blobs) => (Some(blobs.clone()), None),
    76→            AvailableBlockData::DataColumns(data_columns) => (None, Some(data_columns.clone())),
    77→        };
    78→
    79→        let item = CacheItem {
    80→            epoch,
    81→            committee_lengths,
    82→            beacon_block_root,
    83→            source,
    84→            target,
    85→            block: block.block_cloned(),
    86→            blobs,
    87→            data_columns,
    88→            proto_block,
    89→        };
    90→
    91→        *self.item.write() = Some(item);
    92→
    93→        Ok(())
    94→    }
