    96→    /// Will return `Some(attestation)` if all the following conditions are met:
    97→    ///
    98→    /// - There is a cache `item` present.
    99→    /// - If `request_slot` is in the same epoch as `item.epoch`.
   100→    /// - If `request_index` does not exceed `item.committee_count`.
   101→    pub fn try_attest(
