   103→        request_slot: Slot,
   104→        request_index: CommitteeIndex,
   105→        spec: &ChainSpec,
   106→    ) -> Result<Option<Attestation<E>>, Error> {
   107→        let lock = self.item.read();
   108→        let Some(item) = lock.as_ref() else {
   109→            return Ok(None);
